head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사)
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	window.log = log1 = "";
	scwin.data4 = [
		"", "sample1", "1",
		"", "sample1", "2",
		"", "sample1", "3",
		"", "sample1", "4",
		"", "sample1", "5",
		"", "sample2", "6",
		"", "sample2", "7",
		"", "sample2", "8",
		"", "sample3", "9",
		"", "sample3", "10",
		"", "sample3", "11",
		"", "sample4", "12",
		"", "sample5", "13",
		"", "sample4", "14",
		"", "sample5", "15",
		"", "sample5", "16",
		"", "sample2", "17",
		"", "sample3", "18",
		"", "sample1", "19"
	];
	dataList1.setData(scwin.data4.slice(0));
};
scwin.grid1_ongroupby = function(options) {
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
	return true;
};
scwin.grid1_oncellclick = function(row, col) {
	log = "row:: " + row + " col::" + col;
	log1 = "getCellData ::" + dataList1.getCellData(row, "col3");
	grid1.setCellBackgroundColor(row, col, "yellow");
};
scwin._checkRgb = function(id, hexa) {
	var rgb = scwin.__getJq("#" + id).css("background-color");
	if (rgb.indexOf("rgb") != -1) {
		return rgb == "rgb(255, 255, 0)";
	}
	return rgb == hexa;
};
